INSERT INTO reports (site_id,subsite_id,created_by_user_id,description,category,reporter_urgency,participation_count,status,editable,visibility,reopen_count,created_at,updated_at) SELECT u.site_id,s.id,u.id,'Demo shared plumbing issue','plumbing','medium',1,'open',1,'public',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM users u JOIN subsites s ON s.site_id=u.site_id AND s.label='MAIN' WHERE u.email='reporter1@hotel.fixflow.test' AND NOT EXISTS (SELECT 1 FROM reports r WHERE r.created_by_user_id=u.id AND r.description='Demo shared plumbing issue');
